                    var binder = _bindersByRowKey[rowKey];
                    _bindersByRowKey.Remove(rowKey);
                    _binders.Remove(binder);
                    ItemRemoved?.Invoke(binder);
                    binder.Dispose();
                }
            }
            SortBinders();
        }

        private async Task<CharacterBinder> BuildBinderFromInventoryCharacterUserItem(EzItemSet item, CancellationToken cancellationToken)
        {
            var model = CharacterBinder.CreateModel((string.IsNullOrEmpty(item.ItemName) ? default(CharacterId) : new CharacterId(item.ItemName)), item.ItemSetId);
            ApplyInventoryCharacterUserItemTo(model, item);
            var binder = new CharacterBinder(model, _gs2, _session);
            await binder.MountAsync(cancellationToken);
            return binder;
        }

        private static void ApplyInventoryCharacterUserItemTo(MutableCharacter model, EzItemSet item)
        {
            CharacterBinder.ApplyUserdataInventoryCharacterItemModel(model, item);
        }

        private CharacterId ExtractInventoryCharacterUserIdentity(EzItemSet item)
        {
            return (string.IsNullOrEmpty(item.ItemName) ? default(CharacterId) : new CharacterId(item.ItemName));
        }

        private string? ExtractInventoryCharacterUserRowKey(EzItemSet item)
        {
            var id = ExtractInventoryCharacterUserIdentity(item);
            if (EqualityComparer<CharacterId>.Default.Equals(id, default)) return null;
            if (string.IsNullOrEmpty(item.ItemName) || string.IsNullOrEmpty(item.Name)) return null;
            return $"{item.ItemName}.{item.Name}";
        }

        internal sealed class CharacterBinderComparer : IComparer<IReadOnlyCharacterBinder>
        {
            public static readonly CharacterBinderComparer Default = new CharacterBinderComparer();
            public int Compare(IReadOnlyCharacterBinder? a, IReadOnlyCharacterBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                return Comparer<CharacterId>.Default.Compare(a.Id, b.Id);
            }
        }

        internal sealed class CharacterBinderIdTieBreakComparer : IComparer<IReadOnlyCharacterBinder>
        {
            private readonly IComparer<IReadOnlyCharacterBinder> _inner;
            public CharacterBinderIdTieBreakComparer(IComparer<IReadOnlyCharacterBinder> inner) { _inner = inner; }
            public int Compare(IReadOnlyCharacterBinder? a, IReadOnlyCharacterBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                var c = _inner.Compare(a, b);
                if (c != 0) return c;
                return Comparer<CharacterId>.Default.Compare(a.Id, b.Id);
            }
        }
    }
}
